#define MOD 1000000007LL

/*
We are given a permutation a[1..n] representing the stack from top to bottom.

We move documents one by one from the original stack to one of two temporary piles.
For each temporary pile, from top to bottom numbers must be in decreasing order
(equivalently, when pushing onto a pile, the new number must be larger than the
current top of that pile).

Also each pile has maximum height h.

Question: count the number of ways to assign each document to one of the two piles
so that all constraints hold. If impossible, answer 0.

DP:
Process documents in order.
State = current heights (x, y) of the two piles.
Because each pile must be decreasing from top to bottom, its top is simply the last
assigned element to that pile. To check feasibility efficiently, we use the standard
interval DP idea:

For any segment [1..i], if we know heights of the two piles, then the top elements
of the piles are determined by the last positions assigned to each pile, which is
not enough in naive DP.

A simpler observation for permutations:
For a valid 2-pile assignment with decreasing piles, within each pile the assigned
sequence in processing order must be increasing.

Thus we are counting colorings by two colors such that each color class forms an
increasing subsequence, with each color used at most h times.

For permutations, such a coloring exists iff there is no decreasing subsequence of
length 3 (Dilworth / patience sorting for width 2). We can count colorings by DP
on "conflict edges":
If i<j and a[i]>a[j], then i and j cannot have the same color.

For permutations of width <=2, this conflict graph is bipartite and each connected
component has exactly 2 possible colorings. We only need to count colorings with
global color-class sizes <= h.

We build the inversion graph and test bipartiteness, collecting component color class
sizes (c0, c1). Then subset DP over components:
choose for each component whether its bipartition side 0 goes to pile A or pile B.

This works because same-color vertices must be an increasing subsequence exactly when
every inversion edge connects opposite colors, i.e. proper coloring of inversion graph.

Complexity O(n^2), suitable for moderate n.
*/

typedef struct {
    int *v;
    int sz, cap;
} Vec;

static void vec_push(Vec *a, int x) {
    if (a->sz == a->cap) {
        a->cap = a->cap ? a->cap * 2 : 4;
        a->v = (int*)realloc(a->v, a->cap * sizeof(int));
    }
    a->v[a->sz++] = x;
}

int main(void) {
    int n, h;
    if (scanf("%d %d", &n, &h) != 2) return 0;

    int *a = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);

    Vec *g = (Vec*)calloc(n, sizeof(Vec));

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (a[i] > a[j]) {
                vec_push(&g[i], j);
                vec_push(&g[j], i);
            }
        }
    }

    int *color = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) color[i] = -1;

    int *queue = (int*)malloc(n * sizeof(int));
    int compCnt = 0;
    int *c0 = (int*)malloc(n * sizeof(int));
    int *c1 = (int*)malloc(n * sizeof(int));

    for (int s = 0; s < n; s++) {
        if (color[s] != -1) continue;
        int head = 0, tail = 0;
        queue[tail++] = s;
        color[s] = 0;
        int cnt0 = 1, cnt1 = 0;

        while (head < tail) {
            int u = queue[head++];
            for (int k = 0; k < g[u].sz; k++) {
                int v = g[u].v[k];
                if (color[v] == -1) {
                    color[v] = color[u] ^ 1;
                    if (color[v] == 0) cnt0++;
                    else cnt1++;
                    queue[tail++] = v;
                } else if (color[v] == color[u]) {
                    printf("0\n");
                    return 0;
                }
            }
        }
        c0[compCnt] = cnt0;
        c1[compCnt] = cnt1;
        compCnt++;
    }

    long long *dp = (long long*)calloc(n + 1, sizeof(long long));
    long long *ndp = (long long*)calloc(n + 1, sizeof(long long));
    dp[0] = 1;

    for (int i = 0; i < compCnt; i++) {
        for (int x = 0; x <= n; x++) ndp[x] = 0;
        for (int usedA = 0; usedA <= n; usedA++) if (dp[usedA]) {
            int na = usedA + c0[i];
            if (na <= n) {
                ndp[na] = (ndp[na] + dp[usedA]) % MOD;
            }
            na = usedA + c1[i];
            if (na <= n) {
                ndp[na] = (ndp[na] + dp[usedA]) % MOD;
            }
        }
        long long *tmp = dp; dp = ndp; ndp = tmp;
    }

    long long ans = 0;
    for (int sizeA = 0; sizeA <= n; sizeA++) {
        int sizeB = n - sizeA;
        if (sizeA <= h && sizeB <= h) {
            ans = (ans + dp[sizeA]) % MOD;
        }
    }

    printf("%lld\n", ans % MOD);
    return 0;
}

import java.util.Scanner;

public class DocumentStacks {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt(); // number of documents
        int k = sc.nextInt(); // maximum height of each temporary pile

        int[] serials = new int[n];
        for (int i = 0; i < n; i++) {
            serials[i] = sc.nextInt();
        }

        // dp[a][b] = ways to have pile1 height a, pile2 height b
        long[][] dp = new long[k + 1][k + 1];
        dp[0][0] = 1;

        long mod = 1_000_000_007L;

        for (int i = 0; i < n; i++) {
            long[][] next = new long[k + 1][k + 1];
            for (int a = 0; a <= k; a++) {
                for (int b = 0; b <= k; b++) {
                    if (dp[a][b] == 0) continue;
                    // Try to put on pile1
                    if (a + 1 <= k) {
                        if (a == 0 || serials[i] < serials[i - a]) {
                            next[a + 1][b] = (next[a + 1][b] + dp[a][b]) % mod;
                        }
                    }
                    // Try to put on pile2
                    if (b + 1 <= k) {
                        if (b == 0 || serials[i] < serials[i - b - a]) {
                            // careful: indices need to refer to the correct top of pile2
                            // pile2 top is the last placed on it
                            int idxPile2Top = i - b; // because pile1 has 'a' items before
                            if (b == 0 || serials[i] < serials[idxPile2Top - 1]) {
                                next[a][b + 1] = (next[a][b + 1] + dp[a][b]) % mod;
                            }
                        }
                    }
                }
            }
            dp = next;
        }

        long result = 0;
        for (int a = 0; a <= k; a++) {
            for (int b = 0; b <= k; b++) {
                result = (result + dp[a][b]) % mod;
            }
        }

        System.out.println(result);
    }
}

