public class Main {
    static int[] docs;
    static int n, h;
    static Map<Long, Long> memo = new HashMap<>();

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        h = sc.nextInt();
        docs = new int[n];
        for (int i = 0; i < n; i++) docs[i] = sc.nextInt();

        // State: (index, top1, top2, size1, size2)
        // top = 0 means empty pile
        System.out.println(solve(0, 0, 0, 0, 0));
    }

    static long solve(int idx, int top1, int top2, int s1, int s2) {
        if (idx == n) return 1;
        long key = ((long)idx * (n+1) * (n+1) * (h+1) * (h+1)) + ((long)top1 * (n+1) * (h+1) * (h+1)) + ((long)top2 * (h+1) * (h+1)) + ((long)s1 * (h+1)) + s2;
        if (memo.containsKey(key)) return memo.get(key);
        int doc = docs[idx];
        long ways = 0;
        if (s1 < h && (top1 == 0 || doc < top1)) ways += solve(idx+1, doc, top2, s1+1, s2);
        if (s2 < h && (top2 == 0 || doc < top2)) ways += solve(idx+1, top1, doc, s1, s2+1);
        memo.put(key, ways);
        return ways;
    }
}

import java.io.*;
import java.util.*;

/*
We process documents from top to bottom.
Each document must be placed onto one of two temporary piles.

Rules:
1) In each temporary pile, documents must be in reverse order.
   Since the original desired final order is increasing, this means each pile,
   from top to bottom, must be decreasing while we build it.
   If we place items in processing order onto a pile, the last placed item becomes the new top,
   so the pile values from top to bottom are reverse of insertion order.
   Therefore insertion sequence into each pile must be increasing:
   when placing x onto a pile whose current top is t, we need x > t.

2) Each temporary pile height cannot exceed H.

We count the number of valid assignments of the N documents to the two piles.

DP idea:
Let dp[a][b] = number of ways after processing some prefix, where:
- pile 1 currently has height a and top value top1
- pile 2 currently has height b and top value top2

But top values matter, so a naive DP is insufficient.

Observe that only the current top values of both piles matter for future placements.
We can compress states by tracking the heights and top values after each processed prefix.

Since N is not explicitly stated in prompt, we use a hashmap DP over states.
State = (h1, top1, h2, top2), canonicalized by ordering piles to reduce symmetry:
(top1,h1) <= (top2,h2) lexicographically.

Transition for next value x:
- can place on pile 1 if h1 < H and (h1 == 0 || x > top1)
- can place on pile 2 if h2 < H and (h2 == 0 || x > top2)

This counts assignments to two labeled piles. The statement says "two temporary piles";
normally the piles are distinct physical piles, so labeled counting is appropriate.

Input format is not fully specified in the prompt, so we assume:
N H
a1 a2 ... aN
If only N followed by sequence is provided, H cannot be known, so this is the only sensible format.

Output the number of ways. Because the prompt does not specify modulus, use BigInteger.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Integer.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class State {
        int h1, t1, h2, t2;

        State(int h1, int t1, int h2, int t2) {
            // canonicalize to reduce symmetric duplicates
            if (less(h2, t2, h1, t1)) {
                this.h1 = h2; this.t1 = t2;
                this.h2 = h1; this.t2 = t1;
            } else {
                this.h1 = h1; this.t1 = t1;
                this.h2 = h2; this.t2 = t2;
            }
        }

        static boolean less(int hA, int tA, int hB, int tB) {
            if (tA != tB) return tA < tB;
            return hA < hB;
        }

        @Override
        public boolean equals(Object o) {
            if (!(o instanceof State)) return false;
            State s = (State) o;
            return h1 == s.h1 && t1 == s.t1 && h2 == s.h2 && t2 == s.t2;
        }

        @Override
        public int hashCode() {
            int res = h1;
            res = res * 31 + t1;
            res = res * 31 + h2;
            res = res * 31 + t2;
            return res;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        if (N == Integer.MIN_VALUE) return;
        int H = fs.nextInt();

        int[] a = new int[N];
        for (int i = 0; i < N; i++) a[i] = fs.nextInt();

        Map<State, java.math.BigInteger> dp = new HashMap<>();
        dp.put(new State(0, Integer.MIN_VALUE, 0, Integer.MIN_VALUE), java.math.BigInteger.ONE);

        for (int x : a) {
            Map<State, java.math.BigInteger> ndp = new HashMap<>();

            for (Map.Entry<State, java.math.BigInteger> e : dp.entrySet()) {
                State s = e.getKey();
                java.math.BigInteger ways = e.getValue();

                // Place on pile 1
                if (s.h1 < H && (s.h1 == 0 || x > s.t1)) {
                    State ns = new State(s.h1 + 1, x, s.h2, s.t2);
                    ndp.merge(ns, ways, java.math.BigInteger::add);
                }

                // Place on pile 2
                if (s.h2 < H && (s.h2 == 0 || x > s.t2)) {
                    State ns = new State(s.h1, s.t1, s.h2 + 1, x);
                    ndp.merge(ns, ways, java.math.BigInteger::add);
                }
            }

            dp = ndp;
            if (dp.isEmpty()) {
                System.out.println(0);
                return;
            }
        }

        java.math.BigInteger ans = java.math.BigInteger.ZERO;
        for (java.math.BigInteger v : dp.values()) ans = ans.add(v);
        System.out.println(ans);
    }
}

