#include <boost/multiprecision/cpp_int.hpp>
using boost::multiprecision::cpp_int;

struct Key {
    int pos, last1, last2, h1, h2;
    bool operator==(const Key& other) const {
        return pos == other.pos && last1 == other.last1 && last2 == other.last2 &&
               h1 == other.h1 && h2 == other.h2;
    }
};

struct KeyHash {
    size_t operator()(Key const& k) const {
        size_t h = 1469598103934665603ULL;
        auto mix = [&](uint64_t x) {
            h ^= x + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2);
        };
        mix(k.pos);
        mix(k.last1);
        mix(k.last2);
        mix(k.h1);
        mix(k.h2);
        return h;
    }
};

int n, H;
vector<long long> a;
unordered_map<Key, cpp_int, KeyHash> memo;

cpp_int dfs(int pos, int last1, int last2, int h1, int h2) {
    if (pos == n) return 1;

    Key key{pos, last1, last2, h1, h2};
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;

    cpp_int ans = 0;
    long long x = a[pos];

    // Put on pile 1: must keep pile decreasing top->bottom,
    // so newly pushed x must be smaller than current top.
    if (h1 < H && (last1 == -1 || x < a[last1])) {
        ans += dfs(pos + 1, pos, last2, h1 + 1, h2);
    }

    // Put on pile 2
    if (h2 < H && (last2 == -1 || x < a[last2])) {
        ans += dfs(pos + 1, last1, pos, h1, h2 + 1);
    }

    memo[key] = ans;
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n >> H)) return 0;
    a.resize(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    cpp_int ans = dfs(0, -1, -1, 0, 0);
    cout << ans << '\n';
    return 0;
}
